#!/usr/bin/env bash
# Commit the rules that PASSED validation (self-healed text plus compliance tags), locally.
#
#   ci_heal.sh PLAN_DIR          (needs passed.z / failed.z from ci_validate.sh)
#
# - Autogenerated rules arrive without compliance tags, so each passed rule is run through
#   tools/tag_compliance.py --write --files <rule>. A technique that is not in the mapping
#   (or any tagger error) only logs a line; the rule is committed without the tags.
# - Rules that failed validation are restored to their pushed content so a half-healed file is
#   never committed and cannot block the later `git pull --rebase`.
# - The commit message carries [skip ci]; the push uses GITHUB_TOKEN (which does not start
#   workflow runs) so the heal commit cannot retrigger deploy-detections.yml.
# Writes committed=true|false to $GITHUB_OUTPUT.
set -u
export GIT_LITERAL_PATHSPECS=1   # file names are paths, never pathspec patterns
plan=${1:?usage: ci_heal.sh PLAN_DIR}
py=${PYTHON:-python}
out=${GITHUB_OUTPUT:-/dev/null}

if [ -s "$plan/failed.z" ]; then
  while IFS= read -r -d '' file; do
    git checkout -- "$file" 2>/dev/null || true
  done < "$plan/failed.z"
fi

if [ -s "$plan/passed.z" ]; then
  while IFS= read -r -d '' file; do
    if "$py" tools/tag_compliance.py --write --files "$file" < /dev/null; then
      echo "compliance tags up to date: $file"
    else
      echo "::notice::compliance tagging skipped for $file (technique not mapped or tagger error); committing without compliance tags"
    fi
    git add -- "$file"
  done < "$plan/passed.z"
fi

if git diff --cached --quiet; then
  echo "No rules were modified by the self-healer or the tagger"
  echo "committed=false" >> "$out"
else
  git -c user.name="github-actions[bot]" -c user.email="github-actions[bot]@users.noreply.github.com" \
    commit -q -m "auto-heal: self-healed and tagged sigma rules [skip ci]" || exit 1
  echo "Committed healed rules locally"
  echo "committed=true" >> "$out"
fi
exit 0
